{
  name: "list_issues",
  description: "List issues, filtered by status and/or assignee. Use to browse or enumerate issues; use search_issues to find issues by text in title or body, and get_issue for one known ID. Returns at most limit issues (default 50). Comments are included by default, so set include_comments to false for smaller responses.",
  params: {
    status: z.string().optional().describe("Filter by issue status. One of: open, in_progress, blocked, closed. Other values return an error. Omit for all statuses."),
    assignee: z.string().optional(),
    include_comments: z.boolean().optional(),
    limit: z.number().optional(),
  },
}

